class Counter {
    private int value = 0;
    void increment() { value++; } // NIEATOMOWE
    int getValue() { return value; }
}
Counter counter = new Counter();
int threadCount = 4, incrementsPerThread = 500_000;
int expected = threadCount * incrementsPerThread;
Thread[] threads = new Thread[threadCount];
for (int i = 0; i < threadCount; i++) {
    threads[i] = new Thread(() -> { for (int j=0;j<incrementsPerThread;j++) counter.increment(); });
}
for (Thread t : threads) t.start();
for (Thread t : threads) t.join();
System.out.println(counter.getValue() + " vs oczekiwane " + expected); // czesto MNIEJ niz expected

