// RACE CONDITION (ta lekcja): utrata aktualizacji przy jednoczesnym odczyt-modyfikuj-zapisz
// VISIBILITY (Lesson08): watek B moze nie widziec wartosci zapisanej przez watek A z powodu cache'owania
Counter c = new Counter();
// 2 watki x 200_000 inkrementacji jak wczesniej

String runRaceExperiment(int threadCount, int incrementsPerThread) throws InterruptedException {
    Counter c = new Counter();
    Thread[] t = new Thread[threadCount];
    for (int i=0;i<threadCount;i++) t[i] = new Thread(() -> { for (int j=0;j<incrementsPerThread;j++) c.increment(); });
    for (Thread th : t) th.start();
    for (Thread th : t) th.join();
    int expected = threadCount*incrementsPerThread;
    int actual = c.getValue();
    return String.format("watki=%d oczekiwany=%d rzeczywisty=%d zgubione=%d wykryto=%b",
        threadCount, expected, actual, expected-actual, expected!=actual);
}
System.out.println(runRaceExperiment(2,100_000));
System.out.println(runRaceExperiment(4,100_000));
System.out.println(runRaceExperiment(8,50_000));

// (a) race-prone: 8 watkow x 50_000 na wspolnym Counter, zmierz czas i poprawnosc
