boolean detectRaceCondition(int threadCount, int incrementsPerThread, int repetitions) throws InterruptedException {
    int expected = threadCount * incrementsPerThread;
    for (int r = 0; r < repetitions; r++) {
        Counter c = new Counter();
        // uruchom threadCount watkow x incrementsPerThread
        if (c.getValue() != expected) return true;
    }
    return false;
}
System.out.println(detectRaceCondition(2, 100_000, 10));
System.out.println(detectRaceCondition(8, 500_000, 10));

